    const e = b.elements.logo,
      q = rotatePoint(pt.x - e.x, pt.y - e.y, -(e.angle || 0)),
      h = e.size / (logoAspects.get(b.id) || 3),
      off =
        e.align === "center" ? -e.size / 2 : e.align === "right" ? -e.size : 0;
