    if (mode === "zip" && items.length) {
      setExportProgress(
        plan.length,
        plan.length + 1,
        "ZIP wird zusammengestellt …",
      );
      await new Promise((resolve) => setTimeout(resolve, 20));
      download(
        MKWBrowser.zip(items),
        MKW.projectName(p.meta) + "_" + settings.format.toUpperCase() + ".zip",
      );
    }
    const successes = plan.length - failures.length;
    $("#exportStatus").textContent =
      `${successes} von ${plan.length} Dateien ${mode === "zip" ? "als ZIP an den Browser übergeben" : "gespeichert"}.${failures.length ? " " + failures.join(" · ") : ""}`;
    setExportProgress(
      plan.length,
      plan.length,
      failures.length
        ? "Abgeschlossen mit Hinweisen"
        : "Fertig · " + successes + " Dateien",
    );
