function carouselFile(target = null) {
  const input = $("#carouselFile");
  input.value = "";
  input.multiple = !target;
  input.onchange = (ev) => carouselImport([...ev.target.files], target);
  input.click();
}

async function carouselImport(files, target) {
  if (!files.length || busy) return;
  carouselEndText();
  busy = true;
  $("#importDialog").showModal();
  let imported = 0;
  try {
    checkpoint();
    for (const [index, file] of [...files].entries()) {
      showImportStage(index, files.length, file.name, 0);
      $("#importExplanation").textContent =
        "Dein Bild wird geladen und in den Carousel-Rahmen eingesetzt.";
      if (file.size > 100 * 1024 * 1024)
        throw Error("Maximal 100 MB pro Bild.");
      const normalized = await (await api("/api/import", file)).json(),
        im = {
          ...normalized,
          id: uid(),
          name: file.name,
          original: normalized.data,
        };
      await image(im.data);
      p.images.push(im);
      let o = p.carousel.objects.find((o) => o.id === target);
      if (!o) {
        o = carouselDefault("image", {
          h: p.carousel.h,
          w: Math.min((im.width / im.height) * p.carousel.h, 100000),
          y: 0,
        });
        p.carousel.objects.unshift(o);
      }
      o.imageId = im.id;
      if (carouselIsVector(o)) {
        o.fillMode = "image";
        o.fillEnabled = true;
      } else o.name = file.name;
      o.scale = 1;
      o.panX = o.panY = 0;
      carouselSelection = o.id;
      carouselUI.ids = new Set([o.id]);
      imported++;
    }
    changed();
    status(`${imported} Bilder im Carousel platziert.`);
  } catch (e) {
    if (imported) changed();
    status(e.message);
  } finally {
    busy = false;
    $("#importDialog").close();
    carouselPanel();
  }
}

function carouselDuplicate() {
  const objects = carouselSelected().filter((o) => !o.locked);
  if (!objects.length) return;
  checkpoint();
  const copies = objects.map((o) => ({
    ...clone(o),
    id: uid(),
    x: o.x + 30,
    y: o.y + 30,
  }));
  p.carousel.objects.push(...copies);
  carouselUI.ids = new Set(copies.map((o) => o.id));
  carouselSelection = copies.at(-1).id;
  changed();
}

function carouselDelete() {
  const ids = carouselSelected()
    .filter((o) => !o.locked && o.type !== "logo")
    .map((o) => o.id);
  if (!ids.length) return;
  checkpoint();
  p.carousel.objects = p.carousel.objects.filter((o) => !ids.includes(o.id));
  carouselSelection = null;
  carouselUI.ids.clear();
  changed();
}

function carouselLayerOrder(direction) {
  const selectedIds = new Set(
    carouselSelected()
      .filter((o) => o.type !== "logo")
      .map((o) => o.id),
  );
  if (!selectedIds.size) return;
  let a = p.carousel.objects.filter((o) => o.type !== "logo");
  const logos = p.carousel.objects.filter((o) => o.type === "logo");
  if (direction === "front" || direction === "back") {
    const chosen = a.filter((o) => selectedIds.has(o.id)),
      rest = a.filter((o) => !selectedIds.has(o.id));
    a = direction === "front" ? [...rest, ...chosen] : [...chosen, ...rest];
  } else if (direction === "up") {
    for (let i = a.length - 2; i >= 0; i--)
      if (selectedIds.has(a[i].id) && !selectedIds.has(a[i + 1].id))
        [a[i], a[i + 1]] = [a[i + 1], a[i]];
  } else {
    for (let i = 1; i < a.length; i++)
      if (selectedIds.has(a[i].id) && !selectedIds.has(a[i - 1].id))
        [a[i], a[i - 1]] = [a[i - 1], a[i]];
  }
  const next = [...a, ...logos];
  if (next.every((o, i) => o === p.carousel.objects[i])) return;
  checkpoint();
  p.carousel.objects = next;
  changed();
}

function carouselKeepLogosOnTop(c = p.carousel) {
  const first = c.objects.findIndex((o) => o.type === "logo");
  if (first < 0 || !c.objects.slice(first).some((o) => o.type !== "logo"))
    return;
  c.objects = [
    ...c.objects.filter((o) => o.type !== "logo"),
    ...c.objects.filter((o) => o.type === "logo"),
  ];
}


// static/carousel-render.js
"use strict";
// Carousel render: see ARCHITECTURE.md for ownership and load order.
async function carouselPaint(
  ctx,
  slide = null,
  scale = 1,
  transparent = false,
  editingId = null,
  objects = null,
  isCurrent = () => true,
  loadImage = image,
) {
  const project = p,
    c = project.carousel;
  carouselKeepLogosOnTop(c);
  ctx.save();
  ctx.scale(scale, scale);
  if (slide !== null) {
    ctx.beginPath();
    ctx.rect(0, 0, c.w, c.h);
    ctx.clip();
    ctx.translate(-slide * c.w, 0);
  }
  if (!transparent) {
    ctx.fillStyle = c.bg;
    ctx.fillRect(0, 0, c.w * c.n, c.h);
  }
  for (const o of objects || c.objects) {
    if (!isCurrent()) break;
    if (o.visible === false || o.id === editingId) continue;
    // Photos clipped to other slides must not repeatedly decode during each export.
    if (
      slide !== null &&
      o.type === "image" &&
      !carouselImageOnSlide(o, slide, c)
    )
      continue;
    ctx.save();
    ctx.globalAlpha = o.opacity ?? 1;
    ctx.globalCompositeOperation = o.blend || "source-over";
    ctx.translate(o.x, o.y);
    if (o.type === "text") {
      ctx.fillStyle = studioPaintRGBA(o.color, o.textAlpha ?? 1);
      ctx.textBaseline = "top";
      ctx.textAlign = "left";
      const layout = carouselTextLayout(o, ctx),
        offset = carouselTextOffset(o, layout);
      for (const line of layout.lines) {
        ctx.font = `${line.size}px "${o.font}"`;
        ctx.fillText(line.text, line.x, line.y + offset);
      }
    } else if (carouselIsVector(o)) {
      await carouselPaintVector(ctx, o, loadImage);
    } else if (o.type === "gradient") {
      if (o.gradientFillMode === "image") ctx.globalAlpha *= o.startAlpha ?? 1;
      ctx.fillStyle = await studioCanvasPaint(ctx, o, "fill", loadImage);
      ctx.fillRect(0, 0, o.w, o.h);
    } else if (o.type === "logo") {
      const im = await image(
        o.source === "black"
          ? "mkw-logo-bold-pos.svg"
          : "mkw-logo-bold-neg.svg",
      );
      ctx.drawImage(im, 0, 0, o.w, o.h);
    } else {
      if (o.type === "angle") {
        const path = carouselAngleMask(o);
        ctx.save();
        ctx.shadowColor =
          o.glowColor +
          Math.round(o.glowAlpha * 255)
            .toString(16)
            .padStart(2, "0");
        ctx.shadowBlur = o.glow * scale;
        ctx.fillStyle = "#ffffff";
        ctx.fill(path);
        ctx.restore();
        ctx.clip(path);
      } else {
        ctx.clip(carouselImageMask(o));
      }
      const im = project.images.find((im) => im.id === o.imageId);
      if (im) {
        const bitmap = await loadImage(im.data),
          fw = o.w,
          fh = o.h,
          s = Math.max(fw / im.width, fh / im.height) * o.scale;
        ctx.translate(fw / 2 + o.panX, fh / 2 + o.panY);
        ctx.scale(o.flipX, o.flipY);
        ctx.drawImage(
          bitmap,
          (-im.width * s) / 2,
          (-im.height * s) / 2,
          im.width * s,
          im.height * s,
        );
      } else {
        ctx.fillStyle = "#68768b";
        ctx.fillRect(0, 0, o.w, o.h);
      }
    }
    ctx.restore();
  }
  ctx.restore();
}

function carouselImageOnSlide(o, slide, c = p.carousel) {
  const points = carouselFramePoints(o),
    xs = points.map((point) => o.x + point.x * o.w),
    ys = points.map((point) => o.y + point.y * o.h);
  // Custom vertices can extend beyond the stored frame. Merely touching an edge
  // contributes no pixels to that slide.
  return (
    Math.max(...xs) > slide * c.w &&
    Math.min(...xs) < (slide + 1) * c.w &&
    Math.max(...ys) > 0 &&
    Math.min(...ys) < c.h
  );
}

