  const range = selection.getRangeAt(0),
    offset = (node, pos) => {
      const prefix = document.createRange();
      prefix.selectNodeContents(el);
      prefix.setEnd(node, pos);
      return carouselEditableValue(prefix.cloneContents()).length;
    };
