  const range = document.createRange();
  if (line.firstChild?.nodeType === Node.TEXT_NODE)
    range.setStart(
      line.firstChild,
      Math.max(
        0,
        Math.min(line.firstChild.length, offset - line.dataset.textStart),
      ),
    );
