function carouselLayerPanel() {
  const c = p.carousel;
  carouselKeepLogosOnTop(c);
  const ids = new Set(carouselSelected().map((o) => o.id));
  $("#carouselLayers").innerHTML = [...c.objects]
    .reverse()
    .map(
      (o) =>
        `<div class="carousel-layer ${ids.has(o.id) ? "active" : ""}" data-layer="${o.id}" draggable="${o.type !== "logo"}"><button data-action="visible" aria-label="${o.visible === false ? "Einblenden" : "Ausblenden"}: ${esc(o.name)}">${studioIcon(o.visible === false ? "hidden" : "visible")}</button><button data-action="locked" aria-label="${o.locked ? "Entsperren" : "Sperren"}: ${esc(o.name)}">${studioIcon(o.locked ? "locked" : "unlocked")}</button><button class="carousel-layer-name" data-action="select" title="${esc(o.name)}">${carouselIcon(o.type)}<span>${esc(o.name)}</span>${carouselWarning(o) ? studioIcon("warning", "layer-warning-icon") : ""}</button><button data-action="up" ${o.type === "logo" || c.objects[c.objects.indexOf(o) + 1]?.type === "logo" ? "disabled" : ""} aria-label="Nach vorne: ${esc(o.name)}">${studioIcon("front")}</button><button data-action="down" ${o.type === "logo" || c.objects.indexOf(o) === 0 ? "disabled" : ""} aria-label="Nach hinten: ${esc(o.name)}">${studioIcon("back")}</button></div>`,
    )
    .join("");
  $("#carouselLayers")
    .querySelectorAll("[data-layer]")
    .forEach((row) => {
      row.ondragstart = (ev) => {
        carouselUI.layerDrag = row.dataset.layer;
        ev.dataTransfer.setData("text/plain", row.dataset.layer);
        ev.dataTransfer.effectAllowed = "move";
      };
      row.ondragover = (ev) => {
        ev.preventDefault();
        row.classList.add("drop-target");
      };
      row.ondragleave = () => row.classList.remove("drop-target");
      row.ondrop = (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        row.classList.remove("drop-target");
        const source = carouselUI.layerDrag,
          target = row.dataset.layer;
        if (!source || source === target) return;
        const index = c.objects.findIndex((o) => o.id === source);
        if (index < 0 || c.objects[index].type === "logo") return;
        checkpoint();
        const [o] = c.objects.splice(index, 1),
          targetIndex = c.objects.findIndex((o) => o.id === target);
        c.objects.splice(targetIndex + 1, 0, o);
        carouselUI.layerDrag = null;
        changed();
      };
      row.ondragend = () => (carouselUI.layerDrag = null);
      row.querySelectorAll("button").forEach(
        (btn) =>
          (btn.onclick = (ev) => {
            const o = c.objects.find((o) => o.id === row.dataset.layer),
              action = btn.dataset.action;
            if (action === "select") {
              if (ev.shiftKey) {
                const set = new Set(carouselSelected().map((o) => o.id));
                set.has(o.id) ? set.delete(o.id) : set.add(o.id);
                carouselSelect([...set]);
              } else carouselSelect([o.id]);
              return;
            }
            if (action === "up" || action === "down") {
              carouselSelect([o.id]);
              carouselLayerOrder(action);
              return;
            }
            checkpoint();
            o[action] = action === "visible" ? o.visible === false : !o.locked;
            changed(false);
            carouselPanel();
          }),
      );
      row.querySelector(".carousel-layer-name").ondblclick = (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const o = c.objects.find((o) => o.id === row.dataset.layer),
          input = document.createElement("input");
        input.value = o.name;
        input.setAttribute("aria-label", "Ebene umbenennen");
        const name = row.querySelector(".carousel-layer-name");
        name.replaceChildren(input);
        input.focus();
        input.select();
        const save = () => {
          if (input.value.trim() && input.value.trim() !== o.name) {
            checkpoint();
            o.name = input.value.trim();
            changed(false);
          }
          carouselLayerPanel();
        };
        input.onblur = save;
        input.onkeydown = (e) => {
          if (e.key === "Enter") input.blur();
          if (e.key === "Escape") {
            input.onblur = null;
            carouselLayerPanel();
          }
        };
      };
    });
}


// static/carousel-geometry.js
"use strict";
// Carousel geometry: see ARCHITECTURE.md for ownership and load order.
function carouselAnglePath(o) {
  const path = new Path2D(),
    w = o.w,
    h = o.h,
    t = Math.min(o.thickness * Math.SQRT2, w * 0.9, h * 0.44);
  path.moveTo(0, 0);
  path.lineTo(w, h / 2);
  path.lineTo(0, h);
  path.lineTo(0, h - t);
  path.lineTo(w - t, h / 2);
  path.lineTo(0, t);
  path.closePath();
  return path;
}

function carouselAngleBleed(o, c = p.carousel, lockedAxis = null) {
  const width = c.w * c.n,
    height = c.h;
  if (lockedAxis !== "x") {
    if (o.x >= width) o.x = width - 1;
    if (o.x + o.w <= 0) o.x = 1 - o.w;
  }
  if (lockedAxis !== "y") {
    if (o.y >= height) o.y = height - 1;
    if (o.y + o.h <= 0) o.y = 1 - o.h;
  }
  const crosses =
    (o.x <= -1 && o.x + o.w > 0) ||
    (o.x + o.w >= width + 1 && o.x < width) ||
    (o.y <= -1 && o.y + o.h > 0) ||
    (o.y + o.h >= height + 1 && o.y < height);
  if (crosses) return;
  const edges = [
    { axis: "x", value: -1 },
    { axis: "x", value: width - o.w + 1 },
    { axis: "y", value: -1 },
    { axis: "y", value: height - o.h + 1 },
  ]
    .filter((edge) => edge.axis !== lockedAxis)
    .sort(
      (a, b) => Math.abs(o[a.axis] - a.value) - Math.abs(o[b.axis] - b.value),
    );
  o[edges[0].axis] = edges[0].value;
}

function carouselAngleMask(o) {
  const canonical = o.direction === "right" ? o : { ...o, w: o.h, h: o.w },
    path = carouselAnglePath(canonical);
  if (o.direction === "right") return path;
  const result = new Path2D(),
    matrix = new DOMMatrix()
      .translate(o.w / 2, o.h / 2)
      .rotate(o.direction === "up" ? -90 : 90)
      .translate(-canonical.w / 2, -canonical.h / 2);
  result.addPath(path, matrix);
  return result;
}

function carouselImageBounds(o) {
  const im = p.images.find((im) => im.id === o.imageId);
  if (!im) return { x: o.x, y: o.y, w: o.w, h: o.h };
  const scale = Math.max(o.w / im.width, o.h / im.height) * o.scale,
    w = im.width * scale,
    h = im.height * scale;
  return {
    x: o.x + o.w / 2 + o.panX - w / 2,
    y: o.y + o.h / 2 + o.panY - h / 2,
    w,
    h,
  };
}

function carouselImageResize(ev, o, corner) {
  if (o.locked) return;
  const start = carouselPoint(ev),
    b = carouselImageBounds(o),
    base = clone(o);
  let begun = false;
  carouselListen(
    ev,
    (e) => {
      if (!begun) {
        checkpoint();
        begun = true;
      }
      const pt = carouselPoint(e),
        dx = pt.x - start.x,
        dy = pt.y - start.y;
      let w =
          b.w + (corner.includes("e") ? dx : corner.includes("w") ? -dx : 0),
        h = b.h + (corner.includes("s") ? dy : corner.includes("n") ? -dy : 0),
        ratio =
          corner === "n" || corner === "s"
            ? h / b.h
            : corner === "e" || corner === "w"
              ? w / b.w
              : Math.max(w / b.w, h / b.h);
      ratio = Math.max(0.05 / base.scale, Math.min(20 / base.scale, ratio));
      w = b.w * ratio;
      h = b.h * ratio;
      let x = corner.includes("w") ? b.x + b.w - w : b.x,
        y = corner.includes("n") ? b.y + b.h - h : b.y;
      if (e.altKey) {
        x = b.x + (b.w - w) / 2;
        y = b.y + (b.h - h) / 2;
      }
      o.scale = base.scale * ratio;
      o.panX = x + w / 2 - o.x - o.w / 2;
      o.panY = y + h / 2 - o.y - o.h / 2;
      carouselRefresh();
      carouselCoordinates([o]);
    },
    () => {
      if (begun) changed(false);
      carouselPanel();
    },
  );
}

function carouselAngleTip(o) {
  return {
    x: o.x + (o.direction === "right" ? o.w : o.w / 2),
    y:
      o.y + (o.direction === "up" ? 0 : o.direction === "down" ? o.h : o.h / 2),
  };
}

function carouselAngleTipSnap(
  o,
  c = p.carousel,
  tolerance = studioPreferences.snapDistance / carouselZoom,
) {
  const tip = carouselAngleTip(o),
    centers = Array.from({ length: c.n }, (_, i) => (i + 0.5) * c.w),
    nearest = centers.reduce((a, b) =>
      Math.abs(a - tip.x) <= Math.abs(b - tip.x) ? a : b,
    ),
    dy = c.h / 2 - tip.y;
  return {
    x: Math.abs(nearest - tip.x) <= tolerance ? o.x + nearest - tip.x : null,
    y: Math.abs(dy) <= tolerance ? o.y + dy : null,
  };
}

function carouselAngleAlign(o, c = p.carousel) {
  const tip = carouselAngleTip(o),
    candidates = Array.from({ length: c.n }, (_, i) => ({
      axis: "x",
      value: (i + 0.5) * c.w - tip.x + o.x,
    }));
  candidates.push({ axis: "y", value: c.h / 2 - tip.y + o.y });
  let best = null,
    distance = Infinity;
  for (const { axis, value } of candidates) {
    const candidate = { ...o, [axis]: value };
    carouselAngleBleed(candidate, c, axis);
    const score = Math.hypot(candidate.x - o.x, candidate.y - o.y);
    if (score < distance) {
      best = candidate;
      distance = score;
    }
  }
  o.x = best.x;
  o.y = best.y;
}

function carouselFramePoints(o) {
  return (
    o.framePoints || [
      { x: 0, y: 0 },
      { x: 1, y: 0 },
      { x: 1, y: 1 },
      { x: 0, y: 1 },
    ]
  );
}

function carouselImageMask(o) {
  const path = new Path2D(),
    points = carouselFramePoints(o);
  points.forEach((point, i) =>
    path[i ? "lineTo" : "moveTo"](point.x * o.w, point.y * o.h),
  );
  path.closePath();
  return path;
}

const carouselFrameCandidates = [
  { x: 0, y: 0 },
  { x: 0.5, y: 0 },
  { x: 1, y: 0 },
  { x: 1, y: 0.5 },
  { x: 1, y: 1 },
  { x: 0.5, y: 1 },
  { x: 0, y: 1 },
  { x: 0, y: 0.5 },
];

const carouselFrameLabels = [
  "Oben links",
  "Oben Mitte",
  "Oben rechts",
  "Rechts Mitte",
  "Unten rechts",
  "Unten Mitte",
  "Unten links",
  "Links Mitte",
];

function carouselFrameSlots(o) {
  if (o.framePointSlots) return [...o.framePointSlots];
  const count = carouselFramePoints(o).length;
  if (count === 4) return [0, 2, 4, 6];
  if (count === 5)
    return [
      0,
      2,
      4,
      6,
      { top: 1, right: 3, bottom: 5, left: 7 }[o.framePointSide || "right"],
    ].sort((a, b) => a - b);
  return Array.from({ length: count }, (_, index) =>
    Math.round((index * 8) / count),
  );
}

function carouselFrameArea(points) {
  return (
    Math.abs(
      points.reduce((sum, point, index) => {
        const next = points[(index + 1) % points.length];
        return sum + point.x * next.y - next.x * point.y;
      }, 0),
    ) / 2
  );
}

function carouselFramePicker(o) {
  const slots = carouselFrameSlots(o),
    points = carouselFramePoints(o);
  return `<div class="frame-point-selector"><div class="frame-point-heading"><span>Rahmenpunkte</span><strong>${slots.length} / 8</strong></div><div class="frame-point-diagram" role="group" aria-label="Rahmenpunkte auswählen · mindestens drei"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><rect x="10" y="10" width="80" height="80"/><polygon points="${points.map((point) => `${10 + point.x * 80},${10 + point.y * 80}`).join(" ")}"/></svg>${carouselFrameCandidates
    .map((point, slot) => {
      const active = slots.includes(slot),
        remaining = points.filter((_, index) => slots[index] !== slot),
        disabled =
          o.locked ||
          (active &&
            (slots.length <= 3 || carouselFrameArea(remaining) < 0.00001));
      return `<button class="frame-point-choice" data-frame-slot="${slot}" style="left:${10 + point.x * 80}%;top:${10 + point.y * 80}%" aria-label="${carouselFrameLabels[slot]}" title="${carouselFrameLabels[slot]}${disabled && !o.locked ? " · mindestens drei Punkte müssen eine Fläche bilden" : ""}" aria-pressed="${active}" ${disabled ? "disabled" : ""}><span></span></button>`;
    })
    .join(
      "",
    )}</div><p id="framePointHint">3–8 Punkte einzeln an- oder abwählen. Mehrere Punkte sind gleichzeitig auswählbar.</p></div>`;
}

function carouselToggleFrameSlot(o, slot) {
  if (o.locked) return;
  const slots = carouselFrameSlots(o),
    active = slots.includes(slot);
  if (active && slots.length <= 3) return;
  const base = clone(o),
    current = carouselFramePoints(o),
    next = active
      ? slots.filter((value) => value !== slot)
      : [...slots, slot].sort((a, b) => a - b);
  const points = next.map((value) => {
    const index = slots.indexOf(value),
      point = index >= 0 ? current[index] : carouselFrameCandidates[value];
    return { x: base.x + point.x * base.w, y: base.y + point.y * base.h };
  });
  if (carouselFrameArea(points) < 1) return;
  const result = clone(o);
  if (!carouselSetImageFrame(result, base, points)) return;
  checkpoint();
  Object.assign(o, result);
  o.framePointSlots = next;
  delete o.framePointSide;
  carouselUI.framePoints = true;
  carouselUI.content = false;
  carouselUI.tool = "select";
  carouselToolUI();
  changed(false);
  carouselPanel();
}

function carouselDrawFramePoints(o, root, editing) {
  const points = carouselFramePoints(o),
    s = carouselZoom,
    svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.classList.add("carousel-frame-path");
  svg.setAttribute("width", o.w * s);
  svg.setAttribute("height", o.h * s);
  Object.assign(svg.style, { left: o.x * s + "px", top: o.y * s + "px" });
  svg.innerHTML = `<polygon points="${points.map((point) => `${point.x * o.w * s},${point.y * o.h * s}`).join(" ")}"/>`;
  root.append(svg);
  if (editing && !o.locked)
    points.forEach((point, index) => {
      const handle = document.createElement("button");
      handle.className = "carousel-point-handle";
      handle.dataset.framePoint = index;
      handle.setAttribute("aria-label", `Rahmenpunkt ${index + 1} verschieben`);
      handle.style.left = (o.x + point.x * o.w) * s + "px";
      handle.style.top = (o.y + point.y * o.h) * s + "px";
      handle.onpointerdown = (ev) => {
        ev.stopPropagation();
        carouselFramePointDrag(ev, o, index);
      };
      root.append(handle);
    });
}

function carouselFramePointDrag(ev, o, index) {
  if (o.locked) return;
  const start = carouselPoint(ev),
    base = clone(o),
    original = carouselFramePoints(base).map((point) => ({
      x: base.x + point.x * base.w,
      y: base.y + point.y * base.h,
    }));
  let begun = false;
  carouselListen(
    ev,
    (e) => {
      const pt = carouselPoint(e);
      let dx = pt.x - start.x,
        dy = pt.y - start.y;
      if (!begun && Math.hypot(dx, dy) * carouselZoom < 2) return;
      if (!begun) {
        checkpoint();
        begun = true;
      }
      if (e.shiftKey) {
        const angle =
            (Math.round(Math.atan2(dy, dx) / (Math.PI / 4)) * Math.PI) / 4,
          length = Math.hypot(dx, dy);
        dx = Math.cos(angle) * length;
        dy = Math.sin(angle) * length;
      }
      const snap = carouselSnap(
          original[index].x + dx,
          original[index].y + dy,
          { w: 0, h: 0 },
          e.ctrlKey || e.metaKey || e.shiftKey,
        ),
        points = original.map((point) => ({ ...point }));
      points[index] = { x: snap.x, y: snap.y };
      carouselUI.snapLines = snap.guides;
      if (!carouselSetImageFrame(o, base, points)) return;
      carouselRefresh();
      carouselCoordinates([o]);
    },
    () => {
      if (begun) changed(false);
      carouselPanel();
    },
  );
}

function carouselSetImageFrame(o, base, points) {
  const x = Math.min(...points.map((point) => point.x)),
    y = Math.min(...points.map((point) => point.y)),
    w = Math.max(10, Math.max(...points.map((point) => point.x)) - x),
    h = Math.max(10, Math.max(...points.map((point) => point.y)) - y);
  if (w > 100000 || h > 100000 || Math.abs(x) > 100000 || Math.abs(y) > 100000)
    return false;
  const im = p.images.find((im) => im.id === o.imageId),
    oldFit = im ? Math.max(base.w / im.width, base.h / im.height) : 1,
    newFit = im ? Math.max(w / im.width, h / im.height) : 1;
  Object.assign(o, {
    x,
    y,
    w,
    h,
    framePoints: points.map((point) => ({
      x: (point.x - x) / w,
      y: (point.y - y) / h,
    })),
    scale: (base.scale * oldFit) / newFit,
    panX: base.x + base.w / 2 + base.panX - x - w / 2,
    panY: base.y + base.h / 2 + base.panY - y - h / 2,
  });
  return true;
}


// static/carousel-slides.js
"use strict";
// Carousel slides: see ARCHITECTURE.md for ownership and load order.
function carouselSlideControls() {
  const root = $("#carouselSlideControls"),
    c = p.carousel,
    s = carouselZoom;
  if (!root) return;
  if (carouselUI.slide >= c.n) carouselUI.slide = c.n - 1;
  root.innerHTML =
    Array.from(
      { length: c.n },
      (_, i) =>
        `<button class="carousel-slide-tab ${carouselUI.slide === i ? "active" : ""}" data-slide="${i}" style="left:${i * c.w * s}px" aria-label="Slide ${i + 1} auswählen" aria-pressed="${carouselUI.slide === i}">Slide ${i + 1}</button>`,
    ).join("") +
    `<button id="carouselAddSlide" style="left:${c.w * c.n * s + 24}px;top:${(c.h * s) / 2 - 20}px" aria-label="Slide hinzufügen" title="Slide hinzufügen" ${c.n >= 20 ? "disabled" : ""}>${studioIcon("plus")}</button>`;
  root.querySelectorAll("[data-slide]").forEach(
    (btn) =>
      (btn.onclick = (ev) => {
        ev.stopPropagation();
        carouselSlideSelect(+btn.dataset.slide);
      }),
  );
  $("#carouselAddSlide").onclick = (ev) => {
    ev.stopPropagation();
    carouselSlideInsert(c.n);
  };
}

function carouselSlideSelect(index) {
  carouselEndText();
  carouselSelection = null;
  carouselUI.ids.clear();
  carouselUI.slide = index;
  carouselPanel();
  carouselRefresh();
}

function carouselSlidePanel(panel) {
  const c = p.carousel,
    index = carouselUI.slide;
  panel.innerHTML = `<div class="carousel-section-heading"><h3>Slide ${index + 1}</h3><span>Zeichenfläche</span></div><section class="carousel-property-section"><h4>Format</h4><p>${c.w} × ${c.h} px · ${index + 1} von ${c.n} Slides</p></section><section class="carousel-property-section"><h4>Anordnung</h4><div class="carousel-fields"><button id="carouselSlideBefore" ${c.n >= 20 ? "disabled" : ""}>Davor hinzufügen</button><button id="carouselSlideAfter" ${c.n >= 20 ? "disabled" : ""}>Danach hinzufügen</button><button id="carouselSlideLeft" ${index === 0 ? "disabled" : ""}>← Nach links</button><button id="carouselSlideRight" ${index === c.n - 1 ? "disabled" : ""}>Nach rechts →</button></div></section><section class="carousel-property-section"><h4>Slide bearbeiten</h4><button id="carouselSlideDuplicate" ${c.n >= 20 ? "disabled" : ""}>Slide duplizieren</button><button id="carouselSlideDelete" ${c.n <= 2 ? "disabled" : ""}>Slide entfernen</button><p>Beim Entfernen werden vollständig enthaltene Elemente mit entfernt. Übergreifende Elemente bleiben auf der Montagefläche. Das MKW-Logo bleibt erhalten.</p></section>`;
  $("#carouselSlideBefore").onclick = () => carouselSlideInsert(index);
  $("#carouselSlideAfter").onclick = () => carouselSlideInsert(index + 1);
  $("#carouselSlideLeft").onclick = () => carouselSlideMove(-1);
  $("#carouselSlideRight").onclick = () => carouselSlideMove(1);
  $("#carouselSlideDuplicate").onclick = () =>
    carouselSlideInsert(index + 1, index);
  $("#carouselSlideDelete").onclick = carouselSlideDelete;
}

function carouselBoardIndexes() {
  p.boards.forEach((b, i) => (b.carouselSlide = i));
}

function carouselSlideInsert(index, duplicate = null) {
  const c = p.carousel;
  if (c.n >= 20) return;
  carouselEndText();
  checkpoint();
  const copies =
    duplicate === null
      ? []
      : c.objects
          .filter(
            (o) => o.x >= duplicate * c.w && o.x + o.w <= (duplicate + 1) * c.w,
          )
          .map((o) => ({
            ...clone(o),
            id: uid(),
            x: o.x + (index - duplicate) * c.w,
          }));
  c.objects.forEach((o) => {
    if (o.x >= index * c.w) o.x += c.w;
  });
  c.objects.push(...copies);
  c.n++;
  const b = basicBoard(p.images[0], c.w, c.h);
  p.boards.splice(index, 0, b);
  carouselBoardIndexes();
  carouselUI.ids.clear();
  carouselSelection = null;
  carouselUI.slide = index;
  changed();
  carouselSlideCenter(index);
}

function carouselSlideDelete() {
  const c = p.carousel,
    index = carouselUI.slide;
  if (index === null || c.n <= 2) return;
  carouselEndText();
  checkpoint();
  const start = index * c.w,
    end = start + c.w;
  c.objects = c.objects.filter(
    (o) => o.type === "logo" || !(o.x >= start && o.x + o.w <= end),
  );
  c.objects.forEach((o) => {
    if (o.x >= end) o.x -= c.w;
    else if (o.type === "logo" && o.x >= start && o.x < end) {
      o.x = c.w - c.right - o.w;
      o.y = c.top;
    }
  });
  c.n--;
  p.boards.splice(index, 1);
  carouselBoardIndexes();
  carouselUI.ids.clear();
  carouselSelection = null;
  carouselUI.slide = Math.min(index, c.n - 1);
  changed();
  carouselSlideCenter(carouselUI.slide);
}

function carouselSlideMove(delta) {
  const c = p.carousel,
    index = carouselUI.slide,
    next = index + delta;
  if (index === null || next < 0 || next >= c.n) return;
  carouselEndText();
  checkpoint();
  c.objects.forEach((o) => {
    if (o.x >= index * c.w && o.x + o.w <= (index + 1) * c.w)
      o.x += delta * c.w;
    else if (o.x >= next * c.w && o.x + o.w <= (next + 1) * c.w)
      o.x -= delta * c.w;
  });
  [p.boards[index], p.boards[next]] = [p.boards[next], p.boards[index]];
  carouselBoardIndexes();
  carouselUI.slide = next;
  changed();
  carouselSlideCenter(next);
}

function carouselSlideCenter(index) {
  const v = $("#carouselViewport"),
    r = $("#carouselCanvas").getBoundingClientRect(),
    vr = v.getBoundingClientRect();
  v.scrollLeft +=
    r.left +
    (index + 0.5) * p.carousel.w * carouselZoom -
    vr.left -
    v.clientWidth / 2;
}


// static/carousel-bootstrap.js
"use strict";
// Carousel bootstrap: see ARCHITECTURE.md for ownership and load order.
window.addEventListener(
  "keydown",
  (ev) => {
    if (!carouselActive() || busy || document.querySelector("dialog[open]"))
      return;
    const target = ev.target,
      typing =
        target.isContentEditable || target.closest("input,textarea,select");
    if (typing) return;
    const key = ev.key.toLowerCase(),
      command = ev.metaKey || ev.ctrlKey;
    if (studioPicker) return;
    if (carouselVectorKey(ev)) return;
    if (command && key === "z") {
      ev.preventDefault();
      ev.stopImmediatePropagation();
      carouselEndText();
      ev.shiftKey ? redo() : undo();
      return;
    }
    if (command && key === "a") {
      ev.preventDefault();
      carouselSelect(
        p.carousel.objects
          .filter((o) => !o.locked && o.visible !== false)
          .map((o) => o.id),
      );
      return;
    }
    if (command && key === "d") {
      ev.preventDefault();
      carouselDuplicate();
      return;
    }
    if (command && key === "c") {
      ev.preventDefault();
      carouselUI.clipboard = carouselSelected().map(clone);
      carouselUI.clipboardAssets = [...p.images];
      carouselUI.clipboardFonts = [...p.fonts];
      return;
    }
    if (command && key === "v") {
      ev.preventDefault();
      if (carouselUI.clipboard.length) {
        checkpoint();
        for (const im of carouselUI.clipboardAssets || [])
          if (!p.images.some((item) => item.id === im.id)) p.images.push(im);
        for (const font of carouselUI.clipboardFonts || [])
          if (!p.fonts.some((item) => item.role === font.role))
            p.fonts.push(font);
        loadFonts();
        const copies = carouselUI.clipboard.map((o) => ({
          ...clone(o),
          id: uid(),
          x: o.x + 30,
          y: o.y + 30,
        }));
        p.carousel.objects.push(...copies);
        carouselUI.ids = new Set(copies.map((o) => o.id));
        carouselSelection = copies.at(-1).id;
        changed();
      }
      return;
    }
    if (ev.code === "Space") {
      ev.preventDefault();
      carouselUI.space = true;
      carouselToolUI();
      return;
    }
    if (key === "escape") {
      ev.preventDefault();
      carouselEndText();
      if (carouselUI.content) {
        carouselUI.content = false;
        carouselToolUI();
        carouselRefresh();
        carouselPanel();
        return;
      }
      carouselSelect([]);
      carouselUI.tool = "select";
      carouselToolUI();
      return;
    }
    if (key === "delete" || key === "backspace") {
      ev.preventDefault();
      if (carouselUI.slide !== null) carouselSlideDelete();
      else carouselDelete();
      return;
    }
    if (key === "[" || key === "]") {
      ev.preventDefault();
      carouselLayerOrder(
        key === "]"
          ? ev.shiftKey
            ? "front"
            : "up"
          : ev.shiftKey
            ? "back"
            : "down",
      );
      return;
    }
    if (key.startsWith("arrow")) {
      const chosen = carouselSelected().filter((o) => !o.locked);
      if (!chosen.length) return;
      ev.preventDefault();
      checkpoint();
      const delta = ev.shiftKey ? 10 : 1;
      chosen.forEach((o) => {
        if (key === "arrowleft") o.x -= delta;
        if (key === "arrowright") o.x += delta;
        if (key === "arrowup") o.y -= delta;
        if (key === "arrowdown") o.y += delta;
      });
      chosen
        .filter((o) => o.type === "angle")
        .forEach((o) => carouselAngleAlign(o));
      changed(false);
      carouselPanel();
      return;
    }
    if (!command && carouselToolKeys[key]) {
      ev.preventDefault();
      if (key === "m" || key === "l")
        carouselUI.shapeKind = key === "m" ? "rect" : "ellipse";
      carouselTool(carouselToolKeys[key]);
    }
  },
  true,
);

window.addEventListener("keyup", (ev) => {
  if (ev.code === "Space" && carouselUI.space) {
    carouselUI.space = false;
    carouselToolUI();
  }
});

window.addEventListener("blur", () => {
  carouselUI.space = false;
  carouselUI.touches.clear();
  carouselUI.pinch = null;
  carouselToolUI();
});

window.addEventListener("resize", () => {
  if (carouselActive() && $("#carouselViewport")) carouselSetZoom(carouselZoom);
});

carouselSetup();

window.addEventListener(
  "pointerdown",
  (ev) => {
    if (
      !carouselActive() ||
      busy ||
      ev.pointerType !== "touch" ||
      !ev.target.closest?.("#carouselViewport")
    )
      return;
    carouselUI.touches.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (carouselUI.touches.size === 2) {
      carouselUI.drag?.cancel();
      carouselEndText();
      const [a, b] = [...carouselUI.touches.values()];
      carouselUI.pinch = {
        distance: Math.max(1, Math.hypot(a.x - b.x, a.y - b.y)),
        zoom: carouselZoom,
        anchor: carouselPoint({
          clientX: (a.x + b.x) / 2,
          clientY: (a.y + b.y) / 2,
        }),
      };
      ev.preventDefault();
      ev.stopImmediatePropagation();
    }
  },
  true,
);

window.addEventListener(
  "pointermove",
  (ev) => {
    if (!carouselUI.touches.has(ev.pointerId)) return;
    carouselUI.touches.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (!carouselUI.pinch || carouselUI.touches.size < 2) return;
    const [a, b] = [...carouselUI.touches.values()];
    carouselSetZoom(
      (carouselUI.pinch.zoom * Math.hypot(a.x - b.x, a.y - b.y)) /
        carouselUI.pinch.distance,
      { clientX: (a.x + b.x) / 2, clientY: (a.y + b.y) / 2 },
    );
    const v = $("#carouselViewport"),
      r = $("#carouselCanvas").getBoundingClientRect();
    v.scrollLeft +=
      r.left + carouselUI.pinch.anchor.x * carouselZoom - (a.x + b.x) / 2;
    v.scrollTop +=
      r.top + carouselUI.pinch.anchor.y * carouselZoom - (a.y + b.y) / 2;
    ev.preventDefault();
    ev.stopImmediatePropagation();
  },
  true,
);

